select '1. backup table exists' as check, case when exists ( select 1 from information_schema.tables where table_schema = 'public' and table_name = 'planners_backup_0034' ) then 'OK' else 'PROBLEM - 0034 did not run' end as result; select '2. backup covers every plan' as check, case when (select count(*) from public.planners_backup_0034) >= (select count(*) from public.planners) then 'OK' else 'PROBLEM - fewer backed up than exist' end as result, (select count(*) from public.planners) as plans_now, (select count(*) from public.planners_backup_0034) as plans_backed_up; select '3. old example text cleared' as check, case when count(*) = 0 then 'OK' else 'PROBLEM - ' || count(*) || ' plan(s) still carry it' end as result from public.planners where content::text like '%trending audio%' or content::text like '%Craft & Process%' or content::text like '%Kickoff call%'; select '4. every section present' as check, case when count(*) = 0 then 'OK' else 'PROBLEM - ' || count(*) || ' plan(s) missing a section' end as result from public.planners where not (content ?& array[ 'hero','thesis','overview','branding','pillars','format', 'workflow','metrics','competitors','producing','slots','timeline','guarantee' ]); select '5. section headings kept' as check, case when count(*) = 0 then 'OK' else 'PROBLEM - ' || count(*) || ' plan(s) lost their headings' end as result from public.planners where coalesce(content->'branding'->>'heading', '') = '' or coalesce(content->'pillars'->>'heading', '') = '' or coalesce(content->'slots'->>'desc', '') = ''; select '6. branding rows' as check, case when count(*) = 0 then 'OK' else 'PROBLEM - ' || count(*) || ' plan(s) have the wrong rows' end as result from public.planners where jsonb_array_length(content->'branding'->'rows') <> 9; select '7. answers blank' as check, case when count(*) = 0 then 'OK' else 'PROBLEM - ' || count(*) || ' plan(s) still have answers' end as result from public.planners where coalesce(content->'thesis'->>'quote', '') <> '' or coalesce(content->'overview'->>'desc', '') <> '' or coalesce(content->'guarantee'->>'body', '') <> ''; select c.name as client, p.status, p.content->'branding'->'rows'->3->>'label' as fourth_branding_label, p.content->'branding'->'rows'->3->>'ph' as fourth_branding_prompt, p.content->'format'->'stats'->0->>'label' as first_stat_label, p.content->'format'->'stats'->0->>'ph' as first_stat_prompt from public.planners p join public.clients c on c.id = p.client_id order by c.name limit 5;
